examples.code:
.modal-backdrop {
  position: fixed;
  inset: 0;                  /* top, right, bottom, left одной строкой */
  background: rgba(6, 7, 15, .6);
  backdrop-filter: blur(4px);
  z-index: 40;               /* создаёт собственный контекст наложения */
}

.modal {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 41;
}

/* z-index: 9999 внутри .modal не поднимет окно выше соседнего слоя
   с z-index: 42 — числа сравниваются в пределах одного контекста */

